p.write_text(p.read_text()+'\ntest(\'confirmed move-in dates are definitive, flag only after the Pacific date passes, and never auto-mark moved in\',()=>{\n const state=fixture(),tl=engine(state,\'u0\'),l=tl.Lead(\'L_simple_old\');l.referralProgress={programKey:[l.payer,l.building].join(\'|\'),assessment:\'pending\',approval:\'waiting\',moveStatus:\'scheduled\',due:tl.T,note:\'\'};\n l.moveIn=tl.addDays(1);let p=tl.simpleSummary(l);assert.equal(p.scheduled,true);assert.match(p.next,/Confirmed move-in date:/);assert.ok(!p.next.includes(\'Confirm the\'));assert.equal(p.moveInOverdue,false);\n l.moveIn=tl.T;assert.equal(tl.simpleSummary(l).moveInOverdue,false);\n l.moveIn=tl.addDays(-3);p=tl.simpleSummary(l);assert.equal(p.moveInOverdue,true);assert.equal(p.moveInOverdueDays,3);assert.match(p.next,/Move-in overdue/);assert.notEqual(l.stage,\'movein\');\n for(const stage of [\'movein\',\'lost\']){l.stage=stage;assert.equal(tl.simpleSummary(l).moveInOverdue,false);assert.equal(tl.simpleSummary(l).scheduled,false);}\n l.stage=\'new\';l.moveIn=\'invalid\';assert.equal(tl.simpleSummary(l).scheduled,false);assert.equal(tl.simpleSummary(l).moveInOverdue,false);\n const NativeDate=Date;let clock=NativeDate.parse(\'2026-11-18T07:59:00Z\');class ClockDate extends NativeDate{constructor(...args){super(...(args.length?args:[clock]));}static now(){return clock;}}\n l.moveIn=\'2026-11-17\';const ctx={Date:ClockDate,JSON,Math,console,TL_BOOT:{state:tl.S},localStorage:{getItem:()=>null,setItem:()=>{}}};ctx.window=ctx;vm.createContext(ctx);for(const f of [\'data.js\',\'libertana.js\',\'county-roadmap.js\',\'referral-progress.js\',\'api.js\'])vm.runInContext(read(f),ctx);\n assert.equal(ctx.TL.simpleSummary(ctx.TL.Lead(l.id)).moveInOverdue,false);clock=NativeDate.parse(\'2026-11-18T08:01:00Z\');assert.equal(ctx.TL.simpleSummary(ctx.TL.Lead(l.id)).moveInOverdue,true);assert.equal(ctx.TL.simpleSummary(ctx.TL.Lead(l.id)).moveInOverdueDays,1);\n});\ntest(\'homepage age shortcuts and lead age filter combine with approval; owner activity remains private\',()=>{\n const ctx=uiContext(),tl=ctx.TL,{V,UI,filtered,progressFields}=ctx.simpleTest,old=tl.Lead(\'L_simple_old\'),recent=tl.Lead(\'L_simple_new\'),other=tl.Lead(\'L_simple_private\');old.created=tl.addDays(-30);recent.created=tl.addDays(-2);other.created=tl.addDays(-14);old.moveIn=tl.addDays(-1);old.referralProgress={programKey:[old.payer,old.building].join(\'|\'),assessment:\'pending\',approval:\'missing\',moveStatus:\'scheduled\',due:tl.T,note:\'\'};\n const home=V.today(),list=V.leads(),form=progressFields(old);for(const n of [7,14,30])assert.ok(home.includes(\'data-age="\'+n+\'"\'));assert.ok(home.includes(\'Homepage referral age\'));assert.ok(list.includes(\'data-change="openDays"\'));assert.ok(home.includes(\'Team Activity\'));assert.ok(home.includes(\'confirmed move-in date\'));assert.ok(form.includes(\'Confirmed move-in date\'));assert.ok(list.includes(\'MOVE-IN OVERDUE\'));\n UI.openDays=\'14\';assert.deepEqual(Array.from(filtered(),l=>l.id).sort(),[old.id,other.id].sort());UI.simpleApproval=\'approved\';assert.deepEqual(Array.from(filtered(),l=>l.id),[old.id]);UI.moveView=\'moved\';assert.equal(filtered().length,0);\n tl.S.me=\'u2\';assert.ok(!V.today().includes(\'Team Activity\'));assert.ok(!V.today().includes(\'Last sign-in\'));assert.ok(V.today().includes(\'data-age="30"\'));\n});\n')

