(r/"server/archive-building-leads.mjs").write_text("import {randomUUID} from 'node:crypto';\nexport async function archiveRequestedLakesLeads(q,state,env){\n const batch=env.ARCHIVE_LAKES_LEADS_BATCH;if(!batch)return false;\n if(!/^[a-z0-9_-]{8,80}$/.test(batch))throw Error('Invalid Lakes archive batch.');\n const archiveId='archive_lakes_'+batch;if((await q('SELECT data FROM app_state WHERE id=$1',[archiveId])).length)return false;\n let ids;try{ids=JSON.parse(env.ARCHIVE_LAKES_LEAD_IDS||'');}catch{throw Error('Lakes archive requires the reviewed lead IDs.');}\n if(!Array.isArray(ids)||!ids.length||ids.length>1000||ids.some(id=>typeof id!=='string')||new Set(ids).size!==ids.length)throw Error('Invalid Lakes archive selection.');\n const selected=new Set(ids),leads=state.leads.filter(l=>selected.has(l.id));\n if(leads.length!==ids.length||leads.some(l=>l.building!=='lakes')||!state.buildings.some(b=>b.id==='lakes'))throw Error('Lakes archive selection changed; review the records again.');\n const tasks=(state.tasks||[]).filter(t=>selected.has(t.leadId)),archive={version:1,buildingId:'lakes',archivedAt:new Date().toISOString(),archivedBy:'u0',leads,tasks};\n await q('INSERT INTO app_state (id,data) VALUES ($1,$2)',[archiveId,JSON.stringify(archive)]);\n state.leads=state.leads.filter(l=>!selected.has(l.id));state.tasks=(state.tasks||[]).filter(t=>!selected.has(t.leadId));\n await q('INSERT INTO audit_log (id,user_id,action,record_id,field_names,created_at) VALUES ($1,$2,$3,$4,$5,$6)',[randomUUID(),'u0','building_leads.archived','lakes',JSON.stringify(['leads','tasks']),archive.archivedAt]);\n return true;\n}\nexport async function restoreLakesArchive(q,state,archiveId){\n if(!/^archive_lakes_[a-z0-9_-]{8,80}$/.test(archiveId))throw Error('Invalid Lakes archive.');\n const row=(await q('SELECT data FROM app_state WHERE id=$1',[archiveId]))[0];if(!row)throw Error('Archive not found.');const archive=JSON.parse(row.data);\n if(archive.restoredAt)return false;\n if(archive.buildingId!=='lakes'||archive.leads.some(l=>l.building!=='lakes'||state.leads.some(current=>current.id===l.id)))throw Error('Restore conflicts with current records.');\n state.leads.push(...archive.leads);state.tasks.push(...archive.tasks.filter(t=>!state.tasks.some(current=>current.id===t.id)));archive.restoredAt=new Date().toISOString();\n await q('UPDATE app_state SET data=$1 WHERE id=$2',[JSON.stringify(archive),archiveId]);return true;\n}\n")
