(r/"test/lakes-archive.test.mjs").write_text('import test from \'node:test\';import assert from \'node:assert/strict\';import {mkdtempSync,rmSync} from \'node:fs\';import {tmpdir} from \'node:os\';import path from \'node:path\';\nimport {createApplication} from \'../server/index.mjs\';import {initialState,execute} from \'../server/engine.mjs\';import {archiveRequestedLakesLeads,restoreLakesArchive} from \'../server/archive-building-leads.mjs\';\ntest(\'reviewed Lakes removal archives exactly the selected records and tasks, is one-time, and can be restored without touching other buildings\',async()=>{\n const dir=mkdtempSync(path.join(tmpdir(),\'lakes-archive-\')),env={NODE_ENV:\'test\',APP_MODE:\'live\',PHI_APPROVED:\'true\',DATABASE_URL:\'\',SQLITE_PATH:path.join(dir,\'db\')};let app=await createApplication({env,schedule:false});const ids=[];\n try{let state=initialState(false);for(let i=0;i<10;i++){const id=\'L_lakes_test_\'+i;ids.push(id);state=execute(state,\'u0\',{op:\'createLead\',createdId:id,args:[{first:\'Synthetic\',last:\'Lake\'+i,building:\'lakes\',rep:\'u1\',payer:\'Private pay\'}]});}state=execute(state,\'u0\',{op:\'createLead\',createdId:\'L_other_building\',args:[{first:\'Synthetic\',last:\'Other\',building:\'hallmark\',rep:\'u1\',payer:\'Private pay\'}]});state.leads.find(l=>l.id===ids[0]).files=[{id:\'original-encrypted-file\',name:\'Original.pdf\'}];state.tasks=[{id:\'lake_task\',leadId:ids[0]},{id:\'other_task\',leadId:\'L_other_building\'}];const other=JSON.stringify(state.leads.find(l=>l.id===\'L_other_building\')),originalLeads=structuredClone(state.leads);\n await app.store.query(\'UPDATE app_state SET data=$1 WHERE id=$2\',[JSON.stringify(state),\'main\']);await app.close();\n const active={...env,ARCHIVE_LAKES_LEADS_BATCH:\'reviewed_test_batch\',ARCHIVE_LAKES_LEAD_IDS:JSON.stringify(ids)};app=await createApplication({env:active,schedule:false});let current=JSON.parse((await app.store.query(\'SELECT data FROM app_state WHERE id=$1\',[\'main\']))[0].data);assert.equal(current.leads.filter(l=>l.building===\'lakes\').length,0);assert.equal(JSON.stringify(current.leads.find(l=>l.id===\'L_other_building\')),other);assert.deepEqual(current.tasks,[{id:\'other_task\',leadId:\'L_other_building\'}]);\n const archiveId=\'archive_lakes_reviewed_test_batch\',archive=JSON.parse((await app.store.query(\'SELECT data FROM app_state WHERE id=$1\',[archiveId]))[0].data);assert.equal(archive.leads.length,10);assert.equal(archive.leads.find(l=>l.id===ids[0]).files[0].id,\'original-encrypted-file\');\n await app.close();app=await createApplication({env:active,schedule:false});assert.equal((await app.store.query(\'SELECT id FROM audit_log WHERE action=$1\',[\'building_leads.archived\'])).length,1);\n current=JSON.parse((await app.store.query(\'SELECT data FROM app_state WHERE id=$1\',[\'main\']))[0].data);await app.store.transaction(async q=>{assert.equal(await restoreLakesArchive(q,current,archiveId),true);await q(\'UPDATE app_state SET data=$1 WHERE id=$2\',[JSON.stringify(current),\'main\']);});assert.equal(current.leads.length,11);assert.deepEqual(current.leads.find(l=>l.id===ids[0]),originalLeads.find(l=>l.id===ids[0]));assert.equal(await restoreLakesArchive(app.store.query,current,archiveId),false);\n }finally{await app.close();rmSync(dir,{recursive:true,force:true});}\n});\ntest(\'Lakes removal is disabled by default and rejects missing IDs or another building before any write\',async()=>{\n const state=initialState(false),writes=[],q=async(sql,args)=>{if(sql.startsWith(\'SELECT\'))return [];writes.push({sql,args});return [];};assert.equal(await archiveRequestedLakesLeads(q,state,{}),false);\n await assert.rejects(()=>archiveRequestedLakesLeads(q,state,{ARCHIVE_LAKES_LEADS_BATCH:\'test_batch\',ARCHIVE_LAKES_LEAD_IDS:\'["missing"]\'}),/selection changed/);state.leads=[{id:\'wrong-building\',building:\'hallmark\'}];await assert.rejects(()=>archiveRequestedLakesLeads(q,state,{ARCHIVE_LAKES_LEADS_BATCH:\'test_batch\',ARCHIVE_LAKES_LEAD_IDS:\'["wrong-building"]\'}),/selection changed/);assert.equal(writes.length,0);\n});\n')
